package android.hardware;import java.util.*;public class SensorManager {public Map<Integer,Sensor> available=new HashMap<>();public boolean allow=true,denied;public int registered,unregistered,rate;public Sensor selected;public SensorEventListener listener;public Sensor getDefaultSensor(int type){return available.get(type);}public boolean registerListener(SensorEventListener listener,Sensor sensor,int interval){registered++;rate=interval;selected=sensor;if(denied)throw new SecurityException("blocked");this.listener=listener;return allow;}public void unregisterListener(SensorEventListener listener){unregistered++;this.listener=null;}public static void getRotationMatrixFromVector(float[] matrix,float[] vector){System.arraycopy(vector,0,matrix,0,3);}public static void getOrientation(float[] matrix,float[] orientation){System.arraycopy(matrix,0,orientation,0,3);}}
